practice.solution:
package main

import "fmt"

func main() {
	score := 58
	var result string
	if score >= 60 {
		result = "PASS"
	} else {
		result = "FAIL"
	}
	fmt.Println(result)

	diff := 2
	var word string
	if diff == 1 {
		word = "point"
	} else {
		word = "points"
	}
	fmt.Println(diff, word)
}

